{
  "references": [
    {
      "id": "R1",
      "summary_ko": "채소들이 그릇에 떨어지지만 샐러드가 되지 않음."
    },
    {
      "id": "R2",
      "summary_ko": "채소의 정체가 불분명하고 지나치게 길고 비현실적으로 썰려 있으며 상추만 알아볼 수 있음."
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "영상 특징과 픽셀 구조 변화에 따른 형태 및 존재 변화 가능성 감지."
    },
    {
      "id": "C2",
      "summary_ko": "샐러드가 공중에 경직된 채 떠 있다가 그릇으로 떨어지고, 요리사의 손과 자세가 비정상적으로 멈추거나 사라짐."
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "C1은 구체적인 대상이 없는 일반적인 측정 가설이므로 R1과 동일한 현상인지 판단하기에 정보가 부족합니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "R1은 채소가 그릇에 떨어져도 샐러드가 되지 않는다는 점을 지적하지만, C2는 샐러드가 공중에 떠 있다가 그릇에 떨어지는 동작 및 요리사 손의 소멸을 지적하여 결함의 초점이 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "C1은 특정 대상을 명시하지 않은 통계적/픽셀 기반 가설로, R2의 채소 썰린 형태 비현실성 결함과 동일한지 확인할 수 없습니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "R2는 채소 조각의 지나치게 긴 형태와 비현실적인 외관을 다루는 반면, C2는 샐러드의 공중 부양 낙하 및 요리사 신체의 부자연스러운 동결/소멸을 다룹니다."
    }
  ]
}
